try {
/* module-key = 'com.k15t.scroll.scroll-html:spark-web-resource', location = '/com/k15t/scroll/html/ui/app-loaders.js' */
(function(spark) {
    define('scroll-html-app-loaders', ['ajs'], function(AJS) {
        'use strict';

        var appPath = '/plugins/servlet/scroll-html/ui/';

        function getUserLanguageTag() {
            var locale = AJS.params.userLocale;
            if (locale) {
                return locale.replace('_', '-');
            }
            return null;
        }

        function createQueryString(rootCmp, moduleType) {
            var contentId = AJS.params.pageId || '';
            var spaceKey = AJS.params.spaceKey || '';
            var locale = getUserLanguageTag();
            return 'root_cmp=' + rootCmp +
                '&spaceKey=' + encodeURIComponent(spaceKey) +
                '&contentId=' + encodeURIComponent(contentId) +
                '&loc=' + locale +
                '&moduleType=' + moduleType;
        }


        return {
            'scroll-html-exporter-launcher': function(customData, onCloseCallback) {
                AJS.toInit(function() {
                    var query = createQueryString('html-export-dialog', 'dialog');
                    spark.iframeAppLoader.openFullscreenIframeDialog('k15t-exp-html-export-dialog-web-item', appPath, {
                        queryString: query,
                        contextData: customData || {},
                        onClose: onCloseCallback
                    });
                });
            },
            'scroll-html-export-scheme-dialog': function(customData, onCloseCallback) {
                AJS.toInit(function() {
                    var query = createQueryString('html-export-scheme-dialog', 'dialog');
                    spark.iframeAppLoader.openFullscreenIframeDialog('k15t-exp-html-export-scheme-dialog-web-item', appPath, {
                        queryString: query,
                        contextData: customData || {},
                        onClose: onCloseCallback
                    });
                });
            }
        };
    });
})(getSpark());

}catch(e){WRMCB(e)};
;
try {
/* module-key = 'com.k15t.scroll.scroll-html:export-dialog-resources', location = '/com/k15t/scroll/html/ui/export-ui-bootstrap.js' */
require(['ajs', 'jquery', 'scroll-html-app-loaders'], function(AJS, jQuery, scrollAppLaunchers) {
    AJS.toInit(function() {

        'use strict';

        var exportWebItem = jQuery('#com-k15t-confluence-scroll-html-launcher, .scroll-html-launcher');

        function getVariantInformation() {
            var scroll = window.Scroll;
            return scroll &&
                scroll.Versions &&
                scroll.Versions.Context &&
                scroll.Versions.Context.page &&
                scroll.Versions.Context.page.variants;
        }

        function isPageAvailable() {
            var contentAvailable = !jQuery('.sv-content-notavailable').length;
            // information about whether a page is in the current variant is only available since SCM 3.8.0. Default to true otherwise.
            var availableInVariant = true;
            var variantInformation = getVariantInformation();
            if (variantInformation) {
                availableInVariant = variantInformation.isAvailableInCurrentVariant;
            }
            return contentAvailable && availableInVariant;
        }

        // Error dialog that is shown in case the user tries to export a page that is not available.
        var errorDialog = jQuery('' +
            '<section role="dialog" id="k15t-exp-html-no-export-dialog" class="aui-layer aui-dialog2 aui-dialog2-small aui-dialog2-warning"' +
            '         aria-hidden="true">' +
            '    <header class="aui-dialog2-header">' +
            '        <h2 class="aui-dialog2-header-main">Page Not Available</h2>' +
            '        <a class="aui-dialog2-header-close">' +
            '            <span class="aui-icon aui-icon-small aui-iconfont-close-dialog">Close</span>' +
            '        </a>' +
            '    </header>' +
            '    <div class="aui-dialog2-content">' +
            '        <p>You cannot export this page, because it is not available in the current version, variant, or language.</p>' +
            '    </div>' +
            '    <footer class="aui-dialog2-footer">' +
            '        <div class="aui-dialog2-footer-actions">' +
            '            <button id="k15t-exp-html-no-export-dialog-close-button" class="aui-button aui-button-link">Close</button>' +
            '        </div>' +
            '        <div class="aui-dialog2-footer-hint">' +
            '           <span style="' +
            '  background: linear-gradient(to right, #1062fb 0, #1062fb 33.3%, #2eb785 33.3%, #2eb785 66.6%, #ffc420 66.6%);' +
            '  height: .5em;' +
            '  width: 2.625em;' +
            '  display: inline-block;' +
            '  position: relative;' +
            '           "></span>' +
            '         </div>' +
            '    </footer>' +
            '</section>'
        );
        errorDialog.find('#k15t-exp-html-no-export-dialog-close-button').click(function(e) {
            e.preventDefault();
            AJS.dialog2(jQuery(e.target).closest('.aui-dialog2')).hide();
        });
        exportWebItem.append(errorDialog);

        // Register event handler for the export menu entry.
        exportWebItem.on('click', function(event) {
            event.preventDefault();
            if (isPageAvailable()) {
                var exportSchemeId = null;
                var directExportMode = false;

                var exportSchemeIdAttr = jQuery(event.target)
                    .closest(".scroll-html-launcher")
                    .attr("data-export-scheme-id");
                if (exportSchemeIdAttr) {
                    exportSchemeId = exportSchemeIdAttr;
                    directExportMode = true;
                }

                scrollAppLaunchers['scroll-html-exporter-launcher']({
                    exportSchemeId: exportSchemeId,
                    directExportMode: directExportMode
                });
            } else {
                AJS.dialog2('#k15t-exp-html-no-export-dialog').show();
            }
        });


    });
});

}catch(e){WRMCB(e)};
;
